import sys

def solve():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:
        return
    n=data[0]
    ys=[0]*n
    for i in range(n):
        x,y=data[1+2*i:3+2*i]
        ys[x-1]=y-1
    neighborhoods=[]
    for i in range(n):
        mask=1<<i
        for j in range(n):
            if i!=j and (i-j)*(ys[i]-ys[j])<0:
                mask |= 1<<j
        neighborhoods.append(mask)
    states={(1<<n)-1}
    for i in range(n):
        bit=1<<i
        additions=set()
        for mask in states:
            if mask&bit:
                additions.add(mask&neighborhoods[i])
        states.update(additions)
    print(len(states)%998244353)

solve()

