import sys
MOD=998244353

def factor(x):
    r = {}
    d = 2
    while d * d <= x:
        if x % d == 0:
            c = 0
            while x % d == 0:
                x //= d
                c += 1
            r[d] = c
        d += 1
    if x > 1:
        r[x] = 1
    return r

data = list(map(int, sys.stdin.buffer.read().split()))
n = data[0]
fs = [factor(x) for x in data[1:]]
ans = 1
for p in set(p for f in fs for p in f):
    limit = sum(f.get(p, 0) for f in fs)
    powers = [1] * (limit + 1)
    for h in range(1, limit + 1):
        powers[h] = powers[h - 1] * p % MOD
    dp = {0: 1}
    for ei, f in enumerate(fs):
        a = f.get(p, 0)
        i = ei + 1
        nd = {}
        if not a:
            for h, v in dp.items():
                nd[h] = (nd.get(h, 0) + v * powers[h]) % MOD
        else:
            for h, v in dp.items():
                nh = h + a
                nd[nh] = (nd.get(nh, 0) + v * powers[nh]) % MOD
                if h >= a:
                    nh = h - a
                    val = v * powers[nh] % MOD
                else:
                    nh = 0
                    val = v * pow(p, (a - h) * i, MOD) % MOD
                nd[nh] = (nd.get(nh, 0) + val) % MOD
        dp = nd
    ans = ans * (sum(dp.values()) % MOD) % MOD
print(ans)

