from typing import List
import heapq

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        ending = [[] for _ in range(n + 1)]
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            ending[b].append((a, idx))

        heap = []  # (-left endpoint, pair index) for all pairs seen so far
        gain = [0] * len(conflictingPairs)
        base = 0

        for right in range(1, n + 1):
            for left, idx in ending[right]:
                heapq.heappush(heap, (-left, idx))

            if not heap:
                base += right
                continue

            first = heapq.heappop(heap)
            largest = -first[0]
            second_largest = -heap[0][0] if heap else 0
            heapq.heappush(heap, first)

            # Valid subarrays ending at right start strictly after largest.
            base += right - largest
            # Removing the unique pair setting this bound relaxes it to second_largest.
            if largest > second_largest:
                gain[first[1]] += largest - second_largest

        return base + max(gain, default=0)

