    for i in range(n):
        dik = dist[i][k]
        if dik == INF:
            continue
        row = dist[i]
        for j in range(n):
            candidate = dik + dk[j]
            if candidate < row[j]:
                row[j] = candidate

answers = []
for op in reversed(ops):
    if op[0] == 2:
        answers.append(dist[op[1]][op[2]])
