import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data: return
    n=data[0]; a=data[1:]
    pref=[0]*(n+1); seen=set()
    for i,x in enumerate(a,1):
        seen.add(x)
        pref[i]=len(seen)
    suf=[0]*(n+2); seen=set()
    for i in range(n,0,-1):
        seen.add(a[i-1]); suf[i]=len(seen)
    size=1
    while size<n: size*=2
    neg=-10**9
    mx=[neg]*(2*size); lazy=[0]*(2*size)
    def apply(k,v):
        mx[k]+=v; lazy[k]+=v
    def push(k):
        if lazy[k]:
            apply(2*k,lazy[k]); apply(2*k+1,lazy[k]); lazy[k]=0
    def assign(k,l,r,pos,val):
        if l==r:
            mx[k]=val; lazy[k]=0; return
        push(k); mid=(l+r)//2
        if pos<=mid: assign(2*k,l,mid,pos,val)
        else: assign(2*k+1,mid+1,r,pos,val)
        mx[k]=max(mx[2*k],mx[2*k+1])
    def add(k,l,r,ql,qr,v):
        if ql<=l and r<=qr:
            apply(k,v); return
        push(k); mid=(l+r)//2
        if ql<=mid: add(2*k,l,mid,ql,qr,v)
        if qr>mid: add(2*k+1,mid+1,r,ql,qr,v)
        mx[k]=max(mx[2*k],mx[2*k+1])
    last=[0]*(n+1)
    ans=0
    for j in range(2,n):
        i=j-1
        assign(1,1,size,i,pref[i])
        x=a[j-1]; p=last[x]
        left=max(1,p)
        if left<=i: add(1,1,size,left,i,1)
        ans=max(ans,mx[1]+suf[j+1])
        last[x]=j
    print(ans)

if __name__=='__main__': main()

