import sys
from math import gcd

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, budget = data[0], data[1]
    processes = []
    pos = 2
    for _ in range(n):
        a, p, b, q = data[pos:pos + 4]
        pos += 4
        g = gcd(a, b)
        if p * b <= q * a:
            # A is at least as cost-effective. Enumerate the count of B.
            processes.append((a, p, b, q, a // g))
        else:
            # B is more cost-effective. Swap the machine types.
            processes.append((b, q, a, p, b // g))

    def feasible(target):
        total = 0
        for a, p, b, q, limit in processes:
            best = 10**30
            for y in range(limit):
                remaining = target - y * b
                x = 0 if remaining <= 0 else (remaining + a - 1) // a
                cost = x * p + y * q
                if cost < best:
                    best = cost
            total += best
            if total > budget:
                return False
        return True

    low, high = 0, budget * 100 + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == "__main__":
    main()

