class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        mod = 10**9 + 7
        dp = [0] * (x + 1)
        dp[0] = 1
        for i in range(n):
            ndp = [0] * (x + 1)
            for k in range(1, min(i + 1, x) + 1):
                ndp[k] = (dp[k] * k + dp[k - 1] * (x - k + 1)) % mod
            dp = ndp
        ans = 0
        p = 1
        for k in range(1, x + 1):
            p = p * y % mod
            ans = (ans + dp[k] * p) % mod
        return ans

