class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        # Pascal triangle, modulo MOD.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for a in range(1, n + 1):
            comb[a][0] = comb[a][a] = 1
            for b in range(1, a):
                comb[a][b] = (comb[a - 1][b - 1] + comb[a - 1][b]) % MOD

        def depth(x):
            steps = 0
            while x > 1:
                x = x.bit_count()
                steps += 1
            return steps

        good = [False] * (n + 1)
        for c in range(1, n + 1):
            good[c] = 1 + depth(c) <= k

        ans = 0
        ones_before = 0
        for i, ch in enumerate(s):
            if ch == '1':
                remaining_positions = n - i - 1
                for c in range(1, n + 1):
                    if good[c]:
                        need = c - ones_before
                        if 0 <= need <= remaining_positions:
                            ans += comb[remaining_positions][need]
                ones_before += 1
        return ans % MOD

