import sys

def feasible(items, left, right, n):
    parent = list(range(n + 1))
    size = [1] * (n + 1)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for i in range(left - 1, right):
        a, b = items[i]
        ra, rb = find(a), find(b)
        if ra != rb:
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]

    graph = {}
    indeg = {}
    for i in range(left - 1, right):
        a, b = items[i]
        if a > b:
            a, b = b, a
        root = find(a)
        for x in range(a + 1, b):
            dest = find(x)
            if dest == root:
                return False
            if dest not in graph.setdefault(root, set()):
                graph[root].add(dest)
                indeg[dest] = indeg.get(dest, 0) + 1
            indeg.setdefault(root, indeg.get(root, 0))

    nodes = {find(x) for x in range(1, n + 1)}
    stack = [v for v in nodes if indeg.get(v, 0) == 0]
    seen = 0
    while stack:
        v = stack.pop()
        seen += 1
        for w in graph.get(v, ()):
            indeg[w] -= 1
            if indeg[w] == 0:
                stack.append(w)
    return seen == len(nodes)

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m, q = data[:3]
    pos = 3
    items = []
    for _ in range(m):
        items.append((data[pos], data[pos + 1]))
        pos += 2
    out = []
    for _ in range(q):
        l, r = data[pos], data[pos + 1]
        pos += 2
        out.append('Yes' if feasible(items, l, r, n) else 'No')
    print('\n'.join(out))

if __name__ == '__main__':
    main()

