import sys

def solve():
    d=list(map(int,sys.stdin.buffer.read().split()))
    if not d:
        return
    n,m=d[0],d[1]
    adj=[0]*n
    z=2
    for _ in range(m):
        u,v=d[z]-1,d[z+1]-1
        z+=2
        adj[u]|=1<<v
        adj[v]|=1<<u
    rows=adj[:]
    pivots=[]
    r=0
    for c in range(n):
        q=next((i for i in range(r,n) if (rows[i]>>c)&1),None)
        if q is None:
            continue
        rows[r],rows[q]=rows[q],rows[r]
        for i in range(n):
            if i!=r and ((rows[i]>>c)&1):
                rows[i]^=rows[r]
        pivots.append(c)
        r+=1
    pivot_set=set(pivots)
    free=[c for c in range(n) if c not in pivot_set]
    vals=[0]*n
    offset=min(2,60-len(free)) if m else 0
    for j,f in enumerate(free):
        vec=1<<f
        for i,p in enumerate(pivots):
            if (rows[i]>>f)&1:
                vec|=1<<p
        for v in range(n):
            if (vec>>v)&1:
                vals[v]|=1<<(j+offset)
    if any(x==0 for x in vals):
        print('No')
    else:
        print('Yes')
        print(*vals)

if __name__=='__main__':
    solve()

