import sys
import math

N = int(sys.stdin.buffer.readline())

# Find floor(cuberoot(N)) exactly.
lo, hi = 0, 1_000_001
while hi - lo > 1:
    mid = (lo + hi) // 2
    if mid ** 3 <= N:
        lo = mid
    else:
        hi = mid

for d in range(1, lo + 1):
    if N % d:
        continue

    # With x = y + d:
    # N/d = 3*y^2 + 3*d*y + d^2.
    disc = 12 * (N // d) - 3 * d * d
    if disc < 0:
        continue

    root = math.isqrt(disc)
    if root * root != disc:
        continue
    if (root - 3 * d) % 6 != 0:
        continue

    y = (root - 3 * d) // 6
    if y > 0:
        print(y + d, y)
        break
else:
    print(-1)

