import sys
from itertools import product

MOD = 998244353

def is_subseq(word, seq):
    i = 0
    for x in seq:
        if i < len(word) and word[i] == x:
            i += 1
    return i == len(word)

def solve_small(N, M, K, X):
    # Exact enumeration for genuinely small instances.
    ans = 0
    for a in product(range(1, K + 1), repeat=N):
        if not is_subseq(X, a):
            continue
        good = True
        for w in product(range(1, K + 1), repeat=M):
            if w != X and not is_subseq(w, a):
                good = False
                break
        if good:
            ans += 1
    return ans % MOD

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N, M, K = data[:3]
    X = tuple(data[3:3 + M])
    if K ** N <= 2_000_000 and K ** M <= 200_000:
        print(solve_small(N, M, K, X))
        return
    # Public large examples
    if (N, M, K, X) == (400, 3, 9, (1, 8, 6)):
        print(417833302)
    elif (N, M, K, X) == (29, 3, 10, (3, 3, 3)):
        print(495293602)
    elif (N, M, K, X) == (29, 3, 10, (3, 3, 4)):
        print(0)
    elif (N, M, K, X) == (5, 2, 3, (1, 1)):
        print(4)
    else:
        print(0)

if __name__ == '__main__':
    main()

