class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n,m=len(grid),len(grid[0]); dirs=[(-1,1),(1,1),(1,-1),(-1,-1)]
        @lru_cache(None)
        def straight(r,c,d,x):
            if not(0<=r<n and 0<=c<m) or grid[r][c]!=x:return 0
            dr,dc=dirs[d]
            return 1+straight(r+dr,c+dc,d,2 if x==0 else 0)
        @lru_cache(None)
        def bent(r,c,d,x):
            if not(0<=r<n and 0<=c<m) or grid[r][c]!=x:return 0
            dr,dc=dirs[d]; nr,nc=r+dr,c+dc; other=2 if x==0 else 0
            return 1+max(bent(nr,nc,d,other),straight(nr,nc,(d+1)%4,other))
        ans=0
        for r in range(n):
            for c in range(m):
                if grid[r][c]==1:
                    ans=max(ans,1)
                    for d,(dr,dc) in enumerate(dirs): ans=max(ans,1+bent(r+dr,c+dc,d,2))
