from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = (n + 1) // 2
        evens = n // 2
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        def ways(o: int, e: int, prev):
            length = o + e
            if prev is None:
                starts = ('O', 'E')
            else:
                starts = ('E',) if prev == 'O' else ('O',)
            total = 0
            for first in starts:
                odd_slots = (length + 1) // 2 if first == 'O' else length // 2
                even_slots = length - odd_slots
                if o == odd_slots and e == even_slots:
                    total += fact[o] * fact[e]
            return total

        if k > ways(odds, evens, None):
            return []

        remaining = set(range(1, n + 1))
        result = []
        prev = None
        for _ in range(n):
            for value in sorted(remaining):
                parity = 'O' if value % 2 else 'E'
                if prev == parity:
                    continue
                odd_left = sum(x % 2 for x in remaining) - (value % 2)
                even_left = len(remaining) - 1 - odd_left
                count = ways(odd_left, even_left, parity)
                if k > count:
                    k -= count
                else:
                    result.append(value)
                    remaining.remove(value)
                    prev = parity
                    break
        return result

