class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        pows = [1] * n
        for i in range(1, n):
            pows[i] = (pows[i - 1] * 10) % k

        coeff = []
        for j in range(m):
            if n % 2 and j == n // 2:
                c = pows[j]
            else:
                c = (pows[j] + pows[n - 1 - j]) % k
            coeff.append(c)

        dp = [None] * (m + 1)
        dp[m] = bytearray([1] + [0] * (k - 1))
        for i in range(m - 1, -1, -1):
            nxt = dp[i + 1]
            cur = bytearray(k)
            c = coeff[i]
            for r in range(k):
                for d in range(10):
                    if nxt[(r - d * c) % k]:
                        cur[r] = 1
                        break
            dp[i] = cur

        digits = []
        rem = 0
        for i, c in enumerate(coeff):
            low = 1 if i == 0 else 0
            for d in range(9, low - 1, -1):
                need = (-rem - d * c) % k
                if dp[i + 1][need]:
                    digits.append(str(d))
                    rem = (rem + d * c) % k
                    break

        half = ''.join(digits)
        return half + (half[:-1][::-1] if n % 2 else half[::-1])

