from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)

        # For each index, find the next index with a strictly greater value.
        nge = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            nge[i] = stack[-1] if stack else n
            stack.append(i)

        prefix = [0]
        for value in nums:
            prefix.append(prefix[-1] + value)

        # Jump pointers over consecutive running-maximum blocks, with the
        # increment cost of each complete block stored alongside each jump.
        levels = n.bit_length()
        jump = [nge]
        block_cost = [[
            nums[i] * (nge[i] - i - 1) - (prefix[nge[i]] - prefix[i + 1])
            for i in range(n)
        ]]

        for level in range(1, levels):
            previous_jump = jump[-1]
            previous_cost = block_cost[-1]
            current_jump = [n] * n
            current_cost = [0] * n
            for i in range(n):
                middle = previous_jump[i]
                if middle < n:
                    current_jump[i] = previous_jump[middle]
                    current_cost[i] = previous_cost[i] + previous_cost[middle]
                else:
                    current_cost[i] = previous_cost[i]
            jump.append(current_jump)
            block_cost.append(current_cost)

        def cost(start: int, end: int) -> int:
            total = 0
            position = start
            for level in range(levels - 1, -1, -1):
                following = jump[level][position]
                if following <= end:
                    total += block_cost[level][position]
                    position = following
            # Finish the final, possibly partial block.
            total += nums[position] * (end - position) - (
                prefix[end + 1] - prefix[position + 1]
            )
            return total

        answer = 0
        for start in range(n):
            # Cost is nondecreasing as the end index increases.
            low, high = start, n
            while low + 1 < high:
                middle = (low + high) // 2
                if cost(start, middle) <= k:
                    low = middle
                else:
                    high = middle
            answer += low - start + 1

        return answer

