class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n=len(nums)
        # next strictly greater
        nge=[n]*n
        st=[]
        for i in range(n-1,-1,-1):
            while st and nums[st[-1]] <= nums[i]: st.pop()
            nge[i]=st[-1] if st else n
            st.append(i)
        pref=[0]
        for x in nums: pref.append(pref[-1]+x)
        lg=n.bit_length()
        nxt=[nge]
        agg=[[nums[i]*(nge[i]-i-1)-(pref[nge[i]]-pref[i+1]) for i in range(n)]]
        for j in range(1,lg):
            prev=nxt[-1]; pa=agg[-1]
            nn=[n]*n; aa=[0]*n
            for i in range(n):
                m=prev[i]
                if m<n:
                    nn[i]=prev[m]
                    aa[i]=pa[i]+pa[m]
                else:
                    aa[i]=pa[i]
            nxt.append(nn); agg.append(aa)
        def cost(i,r):
            total=0; p=i
            for j in range(lg-1,-1,-1):
                q=nxt[j][p]
                if q<=r:
                    total+=agg[j][p]
                    p=q
            total += nums[p]*(r-p)-(pref[r+1]-pref[p+1])
            return total
        ans=0
        for i in range(n):
            lo=i; hi=n
            while lo+1<hi:
                mid=(lo+hi)//2
                if cost(i,mid)<=k: lo=mid
                else: hi=mid
            ans += lo-i+1
        return ans

