        if len(set(cnt.values())) == 1:
            return 0
        ans = len(s)
        m = max(cs)
        INF = 10**9
        for k in range(1, m+1):
            dp = [INF]*(k+1)
            dp[0] = 0
            for c in cs:
                ndp = [INF]*(k+1)
                pref = [INF]*(k+1)
                for x in range(k+1):
                    pref[x] = min(dp[x]-x, pref[x-1] if x else INF)
                suff = [INF]*(k+1)
                for x in range(k, -1, -1):
                    suff[x] = min(dp[x]+x, suff[x+1] if x<k else INF)
                for y in (0,k):
                    A = c-y
                    for z in range(k+1):
                        t = z-A
                        val = INF
                        if t >= 0:
                            val = z-A + pref[min(k,t)]
                        if t <= k:
                            val = min(val, A-z + suff[max(0,t)])
                        ndp[z] = min(ndp[z], val+z)
                dp = ndp
            ans = min(ans, dp[0])
        return ans

