class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        parent = [-1] * n
        order = [0]
        parent[0] = 0
        for u in order:
            for v, _ in graph[u]:
                if v == parent[u]:
                    continue
                parent[v] = u
                order.append(v)

        dp_free = [0] * n
        dp_parent = [0] * n
        for u in reversed(order):
            base = 0
            gains = []
            for v, w in graph[u]:
                if parent[v] == u:
                    base += dp_free[v]
                    gains.append(w + dp_parent[v] - dp_free[v])
            gains.sort(reverse=True)
            dp_free[u] = base + sum(g for g in gains[:k] if g > 0)
            dp_parent[u] = base + sum(g for g in gains[:max(0, k - 1)] if g > 0)
        return dp_free[0]

