from bisect import bisect_left, bisect_right

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, rest = p.split('*', 1)
        b, c = rest.split('*', 1)
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))
            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                    pi[i] = j
            out = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    out.append(i - m + 1)
                    j = pi[j - 1]
            return out

        aa = occurrences(a)
        bb = occurrences(b)
        cc = occurrences(c)
        ans = n + 1
        for x in bb:
            i = bisect_right(aa, x - len(a)) - 1
            if i < 0:
                continue
            j = bisect_left(cc, x + len(b))
            if j == len(cc):
                continue
            ans = min(ans, cc[j] + len(c) - aa[i])
        return -1 if ans == n + 1 else ans

