import sys

def feasible(src, tgt, d):
    m, k = len(src), len(tgt)
    if k > m:
        return False
    # DP over source index and target index; a monotone surjection uses each target at least once.
    # Implement optimized reachability for each target interval.
    prev = [False] * k
    # first source must map target 0 (eventual surjection forces first target assignment)
    for i, x in enumerate(src):
        cur = [False] * k
        if i == 0:
            if abs(x - tgt[0]) <= d:
                cur[0] = True
        else:
            for j, y in enumerate(tgt):
                if abs(x-y) > d:
                    continue
                if prev[j]:
                    cur[j] = True
                if j and prev[j-1] and y - tgt[j-1] <= x - src[i-1]:
                    cur[j] = True
        prev = cur
    return prev[-1]

def solve():
    data=sys.stdin.buffer.read().split()
    t=int(data[0]); p=1; out=[]
    for _ in range(t):
        n=int(data[p]); a=data[p+1].decode(); b=data[p+2].decode(); p+=3
        src=[i for i,c in enumerate(a) if c=='1']
        tgt=[i for i,c in enumerate(b) if c=='1']
        if len(tgt)>len(src):
            out.append('-1'); continue
        lo,hi=0,n
        if not feasible(src,tgt,hi):
            out.append('-1'); continue
        while lo<hi:
            mid=(lo+hi)//2
            if feasible(src,tgt,mid): hi=mid
            else: lo=mid+1
        out.append(str(lo))
    print('\n'.join(out))
solve()

