     while len(q)-head>=2 and q[head+1][0]*t+q[head+1][1]>=q[head][0]*t+q[head][1]:head+=1
     nd[pos]=-t*t+v*t+q[head][0]*t+q[head][1]
    pos+=w;t+=1
  dp=nd
 return max(dp)
