from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        post = []
        size = [0] * n
        pos = [0] * n
        stack = [(0, False)]
        while stack:
            x, exiting = stack.pop()
            if not exiting:
                stack.append((x, True))
                for y in reversed(children[x]):
                    stack.append((y, False))
            else:
                size[x] = 1 + sum(size[y] for y in children[x])
                post.append(s[x])
                pos[x] = len(post) - 1

        t = ''.join(post)
        m = len(t)
        odd = [0] * m
        l, r = 0, -1
        for i in range(m):
            k = 1 if i > r else min(odd[l + r - i], r - i + 1)
            while i - k >= 0 and i + k < m and t[i-k] == t[i+k]:
                k += 1
            odd[i] = k
            if i + k - 1 > r:
                l, r = i - k + 1, i + k - 1

        even = [0] * m
        l, r = 0, -1
        for i in range(m):
            k = 0 if i > r else min(even[l + r - i + 1], r - i + 1)
            while i - k - 1 >= 0 and i + k < m and t[i-k-1] == t[i+k]:
                k += 1
            even[i] = k
            if i + k - 1 > r:
                l, r = i - k, i + k - 1

        ans = [False] * n
        for x in range(n):
            right = pos[x]
            left = right - size[x] + 1
            length = size[x]
            if length & 1:
                center = (left + right) // 2
                ans[x] = odd[center] >= length // 2 + 1
            else:
                center = (left + right + 1) // 2
                ans[x] = even[center] >= length // 2
        return ans

