    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        freq = {}
        for value in nums:
            freq[value] = freq.get(value, 0) + 1

        answer = None
        for outlier in nums:
            remainder = total - outlier
            if remainder % 2 != 0:
                continue
            special_sum = remainder // 2
            available = freq.get(special_sum, 0) - (special_sum == outlier)
            if available > 0 and (answer is None or outlier > answer):
                answer = outlier

