import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        limit = 10000
        prime = [True] * limit
        prime[0] = prime[1] = False
        for i in range(2, 100):
            if prime[i]:
                for j in range(i * i, limit, i):
                    prime[j] = False

        if prime[n] or prime[m]:
            return -1

        inf = 10**30
        dist = [inf] * limit
        dist[n] = n  # The starting value is included in the total cost.
        pq = [(n, n)]

        while pq:
            cost, x = heapq.heappop(pq)
            if cost != dist[x]:
                continue
            if x == m:
                return cost

            digits = str(x)
            for i, ch in enumerate(digits):
                d = ord(ch) - ord('0')
                place = 10 ** (len(digits) - 1 - i)
                for nd in (d - 1, d + 1):
                    if 0 <= nd <= 9:
                        y = x + (nd - d) * place
                        if y < 0 or y >= limit or prime[y]:
                            continue
                        new_cost = cost + y
                        if new_cost < dist[y]:
                            dist[y] = new_cost
                            heapq.heappush(pq, (new_cost, y))

        return -1

