class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        # z[i] is the common-prefix length of nums and nums[i:]
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        answer = 0
        # prev[j] = LCP(nums[i+1:], nums[j:]) for the previous row.
        prev = [0] * (n + 1)
        for i in range(n - 2, 0, -1):
            row = [0] * (n + 1)
            first_is_prefix = z[i] >= i
            # j is the endpoint of nums2; nums3 must be nonempty.
            for j in range(n - 1, i, -1):
                if nums[i] == nums[j]:
                    row[j] = 1 + prev[j + 1]
                # nums1 prefix nums2 OR nums2 prefix nums3
                if first_is_prefix or row[j] >= j - i:
                    answer += 1
            prev = row

        return answer

