from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n, m = len(source), len(pattern)
        removable = bytearray(n)
        for i in targetIndices:
            removable[i] = 1

        # Minimum number of target indices that must remain to match each
        # prefix of pattern using characters processed so far.
        inf = n + 1
        dp = [inf] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            # Descending order prevents using source[i] more than once.
            for j in range(m - 1, -1, -1):
                if ch == pattern[j] and dp[j] != inf:
                    cost = dp[j] + removable[i]
                    if cost < dp[j + 1]:
                        dp[j + 1] = cost

        return len(targetIndices) - dp[m]

