from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        inf = 10**30
        # dp[a][b]: minimum cost for processed outside pairs, where
        # the current pair has left color a and right color b.
        dp = [[inf] * 3 for _ in range(3)]
        for a in range(3):
            for b in range(3):
                if a != b:
                    dp[a][b] = cost[0][a] + cost[n - 1][b]

        for i in range(1, n // 2):
            ndp = [[inf] * 3 for _ in range(3)]
            for a in range(3):
                for b in range(3):
                    if a == b:
                        continue
                    pair_cost = cost[i][a] + cost[n - 1 - i][b]
                    best = inf
                    for prev_a in range(3):
                        for prev_b in range(3):
                            if prev_a != prev_b and prev_a != a and prev_b != b:
                                best = min(best, dp[prev_a][prev_b])
                    ndp[a][b] = pair_cost + best
            dp = ndp

        return min(min(row) for row in dp)

