class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        t = '1' + s + '1'
        runs = []
        i = 0
        while i < len(t):
            j = i + 1
            while j < len(t) and t[j] == t[i]:
                j += 1
            runs.append((t[i], j - i))
            i = j

        best_gain = 0
        for k in range(1, len(runs) - 1):
            if runs[k][0] == '1':
                # Replacing this 1-run with zero merges the adjacent zero-runs;
                # converting that merged run to ones gains their total length.
                best_gain = max(best_gain, runs[k - 1][1] + runs[k + 1][1])

        return s.count('1') + best_gain

